import { consultarFestivalService } from './service.mjs';

export async function handler(event) {
  const festivalId = Number(event.pathParameters.festivalId);
  const minimo = Number(event.queryStringParameters?.minimo ?? 0);
  const resultado = await consultarFestivalService(festivalId, minimo);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { buscarFestivalRepository, consultarFestivalRepository } from './repository.mjs';

export async function consultarFestivalService(festivalId, minimo) {
  const festival = await buscarFestivalRepository(festivalId);
  if (!festival) throw new Error('Festival no encontrado');
  const actuaciones = await consultarFestivalRepository(festivalId, minimo);
  return { festival, actuaciones };
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_ACTUACION, MODELO_FESTIVAL } from '../../models/festival-actuacion.model.mjs';

export async function buscarFestivalRepository(festivalId) {
  const { Item } = await MODELO_FESTIVAL.build(EntityRepository).get(
    { festivalId },
    { consistent: true }
  );
  return Item ?? null;
}

export async function consultarFestivalRepository(festivalId, minimo) {
  const { Items = [] } = await MODELO_ACTUACION.build(EntityRepository).query(
    { index: 'PorFestival', partition: festivalId },
    { filters: { Actuacion: { attr: 'duracionMinutos', gte: minimo } } }
  );
  return Items;
}
